import mongoose, { Document, Schema } from "mongoose";

export type UserRole = "employer" | "freelancer" | "admin";

export interface IUserOnboarding {
    version: number;
    completedSteps: string[];
    currentStep: string;
    dismissed: boolean;
    welcomeDismissed: boolean;
    completed: boolean;
    tutorialsCompleted: string[];
}

export interface IUser extends Document {
    name: string;
    firstName: string;
    lastName: string;
    email: string;
    passwordHash: string;
    role: UserRole;
    bio: string;
    skills: string[];
    country: string;
    city: string;
    termsAcceptedAt: Date;
    termsVersion: string;
    privacyPolicyVersion: string;
    isVerified: boolean;
    isActive: boolean;
    verificationTokenHash?: string;
    verificationTokenExpiresAt?: Date;
    consumedVerificationTokenHash?: string;
    welcomeEmailSent: boolean;
    verificationResendAt?: Date;
    passwordResetTokenHash?: string;
    passwordResetTokenExpiresAt?: Date;
    paystackRecipientCode?: string;
    payoutBankCode?: string;
    payoutBankName?: string;
    payoutAccountName?: string;
    payoutAccountNumber?: string;
    payoutAccountNumberMasked?: string;
    payoutAccountVerifiedAt?: Date;
    rating?: number;
    reviewCount?: number;
    onboarding: IUserOnboarding;
    adminRemovalGuard: number;
    createdAt: Date;
    updatedAt: Date;
}

const OnboardingSchema = new Schema<IUserOnboarding>({
    version: { type: Number, default: 1 },
    completedSteps: { type: [String], default: [] },
    currentStep: { type: String, default: "" },
    dismissed: { type: Boolean, default: false },
    welcomeDismissed: { type: Boolean, default: false },
    completed: { type: Boolean, default: false },
    tutorialsCompleted: { type: [String], default: [] },
}, { _id: false });

const UserSchema = new Schema<IUser>({
    name: { type: String, required: true, trim: true },
    firstName: { type: String, required: true, trim: true },
    lastName: { type: String, required: true, trim: true },
    email: { type: String, required: true, unique: true, lowercase: true, trim: true },
    passwordHash: { type: String, required: true, select: false },
    role: { type: String, enum: ["employer", "freelancer", "admin"], default: "freelancer" },
    bio: { type: String, default: "" },
    skills: [{ type: String }],
    country: { type: String, required: true, trim: true },
    city: { type: String, required: true, trim: true },
    termsAcceptedAt: { type: Date, required: true },
    termsVersion: { type: String, required: true },
    privacyPolicyVersion: { type: String, required: true },
    isVerified: { type: Boolean, default: false },
    isActive: { type: Boolean, default: true },
    verificationTokenHash: { type: String, select: false },
    verificationTokenExpiresAt: { type: Date, select: false },
    consumedVerificationTokenHash: { type: String, select: false },
    welcomeEmailSent: { type: Boolean, default: false },
    verificationResendAt: { type: Date, select: false },
    passwordResetTokenHash: { type: String, select: false },
    passwordResetTokenExpiresAt: { type: Date, select: false },
    paystackRecipientCode: { type: String, select: false },
    payoutBankCode: { type: String, trim: true, select: false },
    payoutBankName: { type: String, trim: true, select: false },
    payoutAccountName: { type: String, trim: true, select: false },
    payoutAccountNumber: { type: String, match: /^\d{10}$/, select: false },
    payoutAccountNumberMasked: { type: String, trim: true, select: false },
    payoutAccountVerifiedAt: { type: Date, select: false },
    rating: { type: Number, min: 0, max: 5, default: 0 },
    reviewCount: { type: Number, min: 0, default: 0 },
    onboarding: { type: OnboardingSchema, default: () => ({}) },
    adminRemovalGuard: { type: Number, min: 0, default: 0, select: false },
}, { timestamps: true });

const existingUserModel = mongoose.models.User;
if (existingUserModel && !existingUserModel.schema.path("onboarding")) {
    existingUserModel.schema.add({ onboarding: { type: OnboardingSchema, default: () => ({}) } });
}

export default mongoose.models.User || mongoose.model<IUser>("User", UserSchema);
